// 26 Read The Tap
// Works out which button was tapped on which card, pulls the customer name,
// phone and draft from the card itself, and builds the one-tap WhatsApp link.
const q = $json.callback_query || {};
const msg = q.message || {};
const text = String(msg.text || '');
const data = String(q.data || '');
const action = { a: 'Approved', s: 'Skipped', z: 'Seasonal' }[data.split('|')[0]] || 'Unknown';
const title = text.split('\n')[0] || '';
const parts = title.split(' · ');
const customer = (parts.length >= 3 ? parts.slice(1, -1).join(' · ') : data.split('|').slice(1).join('|')).trim();
const phoneM = text.match(/Phone:\s*(\d{10})/);
const phone = phoneM ? phoneM[1] : '';
const di = text.indexOf('Draft:\n');
const draft = di >= 0 ? text.slice(di + 7).trim() : '';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const wa = 'https://wa.me/' + (phone ? '91' + phone : '') + '?text=' + encodeURIComponent(draft);
const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' })).toISOString().slice(0, 10);

let reply;
if (action === 'Approved') {
  reply = `<b>Approved · ${esc(customer)}</b>\n\n${esc(draft)}\n\n<a href="${esc(wa)}">Tap here to open WhatsApp with this message ready</a>` +
    (phone ? '' : '\n<i>No mobile number on file, so WhatsApp will ask you to pick the chat.</i>');
} else if (action === 'Skipped') {
  reply = `<b>Skipped · ${esc(customer)}</b>\nNoted. The desk will not bring this customer up again for a while.`;
} else if (action === 'Seasonal') {
  reply = `<b>Marked seasonal · ${esc(customer)}</b>\nNoted. Treated as a normal seasonal quiet spell, no alert for a while.`;
} else {
  reply = 'That button has expired.';
}
return [{ json: {
  chat_id: String((msg.chat && msg.chat.id) || ''), message_id: String(msg.message_id || ''),
  customer, action, phone, draft, wa_link: wa, reply_html: reply,
  decision_row: { values: [[customer, action, today]] }
} }];

// 07 Sample The Columns
// Reads the Google Sheet tabs, picks the order rows (fresh file or Orders tab)
// and hands Agent 1 only the headers plus 20 sample rows.
const desk = $('06 Load Desk Data').first().json;
const ranges = desk.valueRanges || [];
const tab = (name) => {
  const r = ranges.find(v => String(v.range || '').replace(/'/g, '').split('!')[0] === name);
  return (r && r.values) || [];
};
const kv = (rows) => {
  const o = {};
  for (const r of rows.slice(1)) if (r[0] !== undefined && String(r[0]).trim()) o[String(r[0]).trim()] = r[1] === undefined ? '' : r[1];
  return o;
};

const DEFAULTS = {
  watch_ratio: 1.3, slipping_ratio: 1.8, gone_ratio: 3, min_orders: 4, min_days_late: 3,
  cards: 5, ai_top: 10, snooze_days: 30, seasonal_lookback: 120, allow_discount: 'no',
  language: 'hinglish', email_to: '', owner_chat_id: '', as_of_date: '', business_name: 'Your business',
  dashboard_url: ''
};
const rulesRaw = kv(tab('Rules'));
const rules = { ...DEFAULTS };
for (const [k, v] of Object.entries(rulesRaw)) {
  if (v === '' || v === null) continue;
  rules[k] = typeof DEFAULTS[k] === 'number' && !isNaN(Number(v)) ? Number(v) : String(v).trim();
}
const tone = kv(tab('Tone'));

// where did the orders come from?
let rows = [];
let source = 'sheet';
let chatId = '';
try {
  const t = $('02 Owner Drop Box').first().json;
  chatId = String((t.message && t.message.chat && t.message.chat.id) || '');
} catch (e) { /* Monday run, no Telegram message */ }
let fileRows = null;
try { fileRows = $('05 Open The Spreadsheet').all().map(i => i.json); } catch (e) { fileRows = null; }
if (fileRows && fileRows.length) {
  rows = fileRows;
  source = 'file';
} else {
  const o = tab('Orders');
  const h = (o[0] || []).map(String);
  rows = o.slice(1).filter(r => r.some(x => x !== '' && x !== null && x !== undefined))
    .map(r => Object.fromEntries(h.map((k, i) => [k, r[i] === undefined ? '' : r[i]])));
}
if (!chatId) chatId = String(rules.owner_chat_id || '');

const headers = [];
for (const r of rows.slice(0, 50)) for (const k of Object.keys(r)) if (!headers.includes(k)) headers.push(k);
const sample = rows.slice(0, 20).map(r => headers.map(h => String(r[h] === undefined ? '' : r[h])).join(' | '));
const sample_text = 'HEADERS: ' + headers.join(' | ') + '\nROWS:\n' + sample.join('\n');

return [{ json: {
  source, chat_id: chatId, rules, tone, headers, sample_text, row_count: rows.length, rows,
  decisions: tab('Decisions'), run_log: tab('Run Log'), prev_watch_rows: tab('Watchlist').length,
  prev_order_rows: tab('Orders').length, rules_keys: tab('Rules').map(r => String(r[0] || ''))
} }];

// 09 Check And Clean
// Tests Agent 1's column map against every row. Accepts only if 95% of dates and
// amounts read cleanly. Then cleans: one date format, plain numbers, no returns,
// no duplicate bills. Finally finds look-alike customer names for Agent 2.
const S = $('07 Sample The Columns').first().json;
const parseAgent = (res) => {
  try {
    let t = res.candidates[0].content.parts.map(p => p.text || '').join('');
    t = t.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(t);
  } catch (e) { return {}; }
};
const map = parseAgent($input.first().json);

const findCol = (name) => {
  if (!name) return null;
  const n = String(name).trim().toLowerCase();
  return S.headers.find(h => h.trim().toLowerCase() === n) || null;
};
// fallback guesses so a weak answer from the agent is not fatal
const guess = (re) => S.headers.find(h => re.test(h)) || null;
const col = {
  customer: findCol(map.customer_column) || guess(/party|customer|client|name|buyer/i),
  date: findCol(map.date_column) || guess(/date|dt\b/i),
  amount: findCol(map.amount_column) || guess(/amount|amt|total|value|net|gross/i),
  invoice: findCol(map.invoice_column) || guess(/vch no|invoice|bill no|voucher no|order id|order no/i),
  phone: findCol(map.phone_column) || guess(/mobile|phone|contact|whatsapp/i),
  items: findCol(map.items_column) || guess(/item|product|particular|sku/i),
  type: findCol(map.type_column) || guess(/vch type|voucher type|type|status/i),
};
const order = ['DMY', 'MDY', 'YMD'].includes(map.date_order) ? map.date_order : 'DMY';

const MON = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };
const iso = (y, m, d) => {
  if (y < 100) y += 2000;
  if (!(m >= 1 && m <= 12 && d >= 1 && d <= 31 && y > 1990 && y < 2100)) return null;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCMonth() !== m - 1) return null;
  return dt.toISOString().slice(0, 10);
};
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' || /^\d{5}(\.\d+)?$/.test(String(v))) {
    const n = Number(v);
    if (n > 20000 && n < 80000) return new Date(Date.UTC(1899, 11, 30) + Math.round(n) * 86400000).toISOString().slice(0, 10);
    return null;
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
  if (m) return iso(+m[1], +m[2], +m[3]);
  m = s.match(/^(\d{1,2})[-\/. ]([A-Za-z]{3,4})[A-Za-z]*[-\/. ,]+(\d{2,4})/);
  if (m && MON[m[2].toLowerCase()]) return iso(+m[3], MON[m[2].toLowerCase()], +m[1]);
  m = s.match(/^([A-Za-z]{3,4})[A-Za-z]*[-\/. ](\d{1,2})[-\/. ,]+(\d{2,4})/);
  if (m && MON[m[1].toLowerCase()]) return iso(+m[3], MON[m[1].toLowerCase()], +m[2]);
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/);
  if (m) return order === 'MDY' ? iso(+m[3], +m[1], +m[2]) : iso(+m[3], +m[2], +m[1]);
  return null;
}
function parseAmount(v) {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined) return null;
  let s = String(v).replace(/rs\.?|inr|₹|,|\s/gi, '');
  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
  if (/cr$/i.test(s)) { neg = true; s = s.replace(/cr$/i, ''); }
  s = s.replace(/dr$/i, '');
  if (s === '' || isNaN(Number(s))) return null;
  return neg ? -Number(s) : Number(s);
}

const rows = S.rows;
let nonEmpty = 0, goodDate = 0, goodAmt = 0;
for (const r of rows) {
  if (!col.customer || !String(r[col.customer] || '').trim()) continue;
  nonEmpty++;
  if (col.date && parseDate(r[col.date])) goodDate++;
  if (col.amount && parseAmount(r[col.amount]) !== null) goodAmt++;
}
const dateRate = nonEmpty ? goodDate / nonEmpty : 0;
const amtRate = nonEmpty ? goodAmt / nonEmpty : 0;
const ok = !!(col.customer && col.date && col.amount && nonEmpty >= 10 && dateRate >= 0.95 && amtRate >= 0.95);

if (!ok) {
  return [{ json: {
    ok: false, chat_id: S.chat_id, headers: S.headers, row_count: S.row_count, col,
    date_rate: Math.round(dateRate * 100), amount_rate: Math.round(amtRate * 100)
  } }];
}

// clean
const RETURN_RE = /credit|return|cancel|refund|reversal|\bcn\b|sales ret/i;
const seen = new Set();
const orders = [];
let removedReturns = 0, removedDupes = 0, badRows = 0;
for (const r of rows) {
  const name = String(r[col.customer] || '').replace(/\s+/g, ' ').trim();
  if (!name) continue;
  const date = parseDate(r[col.date]);
  const amount = parseAmount(r[col.amount]);
  if (!date || amount === null) { badRows++; continue; }
  const inv = col.invoice ? String(r[col.invoice] || '').trim() : '';
  const typ = col.type ? String(r[col.type] || '') : '';
  if (amount <= 0 || RETURN_RE.test(typ) || /^(cn|crn|ret|sr)[\/\-]/i.test(inv)) { removedReturns++; continue; }
  const key = inv ? name.toLowerCase() + '|' + inv : name.toLowerCase() + '|' + date + '|' + amount;
  if (seen.has(key)) { removedDupes++; continue; }
  seen.add(key);
  const phone = col.phone ? String(r[col.phone] || '').replace(/\D/g, '').slice(-10) : '';
  orders.push({ customer: name, date, amount: Math.round(amount * 100) / 100, invoice: inv, phone,
    items: col.items ? String(r[col.items] || '').slice(0, 120) : '' });
}

// look-alike names
const STOP = new Set(['pvt', 'ltd', 'private', 'limited', 'co', 'and', 'the', 'ms', 'm s', 'llp', 'company', 'inc']);
const norm = (s) => s.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w && !STOP.has(w)).join(' ');
const grams = (s) => { const g = new Map(); const t = s.replace(/ /g, ''); for (let i = 0; i < t.length - 1; i++) { const k = t.slice(i, i + 2); g.set(k, (g.get(k) || 0) + 1); } return g; };
const dice = (a, b) => { const A = grams(a), B = grams(b); let inter = 0, tot = 0; for (const [k, v] of A) { inter += Math.min(v, B.get(k) || 0); tot += v; } for (const v of B.values()) tot += v; return tot ? 2 * inter / tot : 0; };

const byName = {};
for (const o of orders) {
  const b = byName[o.customer] || (byName[o.customer] = { name: o.customer, n: 0, phones: new Set() });
  b.n++; if (o.phone) b.phones.add(o.phone);
}
const names = Object.values(byName);
const autoMerges = [];
const keyOwner = {};
for (const b of names.sort((a, c) => c.n - a.n)) {
  const k = norm(b.name);
  if (keyOwner[k] && keyOwner[k] !== b.name) autoMerges.push({ from: b.name, into: keyOwner[k], why: 'same name, different spelling of capitals or punctuation' });
  else keyOwner[k] = b.name;
}
const merged = new Set(autoMerges.map(m => m.from));
const live = names.filter(b => !merged.has(b.name));
// shop-type words carry no identity: "Arora Departmental Store" and "Sharma Departmental Store" are not alike
const GENERIC = new Set(['store', 'stores', 'kirana', 'general', 'provision', 'provisions', 'departmental', 'department', 'super', 'mart', 'fresh', 'traders', 'trader', 'trdrs', 'enterprises', 'enterprise', 'medical', 'medicals', 'agencies', 'agency', 'bakers', 'hardware', 'hardwares', 'brothers', 'bros', 'shop', 'centre', 'center', 'sons']);
const core = (s) => norm(s).split(' ').filter(w => !GENERIC.has(w)).join(' ');
const pairs = [];
for (let i = 0; i < live.length; i++) for (let j = i + 1; j < live.length; j++) {
  const a = live[i], b = live[j];
  const samePhone = [...a.phones].some(p => b.phones.has(p));
  const phoneConflict = !samePhone && a.phones.size > 0 && b.phones.size > 0;
  const sim = dice(norm(a.name), norm(b.name));
  const ca = core(a.name), cb = core(b.name);
  const coreSim = ca && cb ? dice(ca, cb) : 0;
  if (samePhone ? sim >= 0.4 : (sim >= 0.72 && coreSim >= 0.8)) {
    pairs.push({ a: a.name, b: b.name, sim: Math.round(sim * 100) / 100, core_sim: Math.round(coreSim * 100) / 100, same_phone: samePhone, phone_conflict: phoneConflict });
  }
}
pairs.sort((x, y) => (y.same_phone - x.same_phone) || (y.sim - x.sim));
const top = pairs.slice(0, 40).map((p, i) => ({ id: 'p' + (i + 1), ...p }));
const pairs_text = top.length
  ? top.map(p => `${p.id}: "${p.a}" vs "${p.b}"${p.same_phone ? ' (same phone number)' : (p.phone_conflict ? ' (different phone numbers)' : '')}`).join('\n')
  : 'NONE';

return [{ json: {
  ok: true, chat_id: S.chat_id, source: S.source, col, date_order: order,
  orders, auto_merges: autoMerges, pairs: top, pairs_text,
  stats: { raw_rows: S.row_count, kept: orders.length, removed_returns: removedReturns, removed_duplicates: removedDupes, unreadable_rows: badRows, customers_before_merge: names.length }
} }];

// 13 Merge Names And Measure Rhythm
// Merges a pair only when Agent 2 says "same" AND the names are very similar,
// or the phone number matches. Unsure pairs stay apart. Then measures each
// customer's own rhythm: usual gap (median), steadiness, bills, yearly value.
const C = $('09 Check And Clean').first().json;
const S = $('07 Sample The Columns').first().json;
const rules = S.rules;
const parseAgent = (res) => {
  try {
    let t = res.candidates[0].content.parts.map(p => p.text || '').join('');
    t = t.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(t);
  } catch (e) { return {}; }
};
const verdicts = {};
for (const d of (parseAgent($input.first().json).decisions || [])) verdicts[d.id] = d;

// union find
const parent = {};
const find = (x) => { while (parent[x] && parent[x] !== x) x = parent[x]; return x; };
const counts = {};
for (const o of C.orders) counts[o.customer] = (counts[o.customer] || 0) + 1;
const union = (a, b) => {
  const ra = find(a), rb = find(b);
  if (ra === rb) return;
  if ((counts[ra] || 0) >= (counts[rb] || 0)) parent[rb] = ra; else parent[ra] = rb;
};
for (const m of C.auto_merges) union(m.into, m.from);
const merges = C.auto_merges.map(m => ({ ...m }));
for (const p of C.pairs) {
  const v = verdicts[p.id];
  const agentSame = v && (v.same === true || String(v.same).toLowerCase() === 'true');
  // different phone numbers on both sides means two businesses, whatever the names say
  if (p.phone_conflict) continue;
  if ((p.same_phone && (agentSame || p.sim >= 0.6)) || (agentSame && p.core_sim >= 0.85 && p.sim >= 0.78)) {
    union(p.a, p.b);
    merges.push({ from: p.b, into: p.a, why: p.same_phone ? 'same phone number' : (v && v.reason) || 'agent and code agree' });
  }
}

// as-of date
const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' }));
const asOf = /^\d{4}-\d{2}-\d{2}$/.test(String(rules.as_of_date || '')) ? String(rules.as_of_date) : today.toISOString().slice(0, 10);
const day = (s) => Math.round(Date.parse(s + 'T00:00:00Z') / 86400000);
const asOfDay = day(asOf);

const median = (a) => { const s = [...a].sort((x, y) => x - y); const n = s.length; return n ? (n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2) : 0; };
const groups = {};
for (const o of C.orders) {
  if (day(o.date) > asOfDay) continue;
  const k = find(o.customer);
  const g = groups[k] || (groups[k] = { name: k, visits: {}, phone: '', phoneDay: -1, items: '' });
  g.visits[o.date] = (g.visits[o.date] || 0) + o.amount;
  if (o.phone && day(o.date) >= g.phoneDay) { g.phone = o.phone; g.phoneDay = day(o.date); }
  if (o.items) g.items = o.items;
}

const customers = Object.values(groups).map(g => {
  const dates = Object.keys(g.visits).sort();
  const days = dates.map(day);
  const bills = dates.map(d => Math.round(g.visits[d]));
  const gaps = days.slice(1).map((d, i) => d - days[i]);
  const med = gaps.length ? median(gaps) : 0;
  const mad = gaps.length ? median(gaps.map(x => Math.abs(x - med))) : 0;
  const avgBill = bills.reduce((a, b) => a + b, 0) / bills.length;
  return {
    name: g.name, phone: g.phone, visits: dates.length, dates, days, bills,
    first_order: dates[0], last_order: dates[dates.length - 1],
    usual_gap: Math.round(med * 10) / 10, gap_mad: Math.round(mad * 10) / 10,
    steadiness: med ? Math.round((mad / med) * 100) / 100 : 0,
    avg_bill: Math.round(avgBill),
    yearly_value: med ? Math.round(avgBill * 365 / med) : 0,
    days_silent: asOfDay - days[days.length - 1],
    last_items: g.items
  };
});

return [{ json: { as_of: asOf, as_of_day: asOfDay, merges, customers, stats: { ...C.stats, customers: customers.length, merged_names: merges.length } } }];

// 14 Judge Status, Season And Money
// Plain arithmetic decides who is slipping. Days silent is compared with each
// customer's own usual gap (irregular buyers get more room). Then the Seasonal
// Guard checks the same weeks last year, past owner decisions are respected,
// and every Slipping or Gone Quiet customer gets a rupee value.
const S = $('07 Sample The Columns').first().json;
const R = $json;
const rules = S.rules;
const asOfDay = R.as_of_day;
const toIso = (d) => new Date(d * 86400000).toISOString().slice(0, 10);
const day = (s) => Math.round(Date.parse(s + 'T00:00:00Z') / 86400000);

// owner decisions (Decisions tab: customer | decision | date)
const lastDecision = {};
for (const r of (S.decisions || []).slice(1)) {
  const name = String(r[0] || '').trim(); if (!name) continue;
  let d = r[2];
  let dd = typeof d === 'number' ? Math.round(d) - 25569 : (/^\d{4}-\d{2}-\d{2}/.test(String(d)) ? day(String(d).slice(0, 10)) : null);
  if (dd === null) continue;
  if (!lastDecision[name] || dd >= lastDecision[name].day) lastDecision[name] = { decision: String(r[1] || ''), day: dd };
}

const ORDER = { 'Gone Quiet': 0, 'Slipping': 1, 'Watch': 2, 'Seasonal': 3, 'Healthy': 4, 'Too New': 5 };
const out = R.customers.map(c => {
  let status;
  let ratio = 0;
  if (c.visits < rules.min_orders || !c.usual_gap) {
    status = 'Too New';
  } else {
    const room = 1 + 0.5 * Math.min(c.steadiness, 1);
    ratio = c.days_silent / (c.usual_gap * room);
    const late = c.days_silent - c.usual_gap;
    if (late < rules.min_days_late || ratio < rules.watch_ratio) status = 'Healthy';
    else if (ratio < rules.slipping_ratio) status = 'Watch';
    else if (ratio < rules.gone_ratio) status = 'Slipping';
    else status = 'Gone Quiet';
  }
  // Seasonal Guard: was this customer also silent in the same weeks last year?
  let seasonal_note = '';
  if (status === 'Slipping' || status === 'Gone Quiet') {
    // last year's version of this silence, with one usual gap of slack at the start
    const ws = c.days[c.days.length - 1] - 365 + Math.max(c.usual_gap, 7), we = asOfDay - 365;
    const firstDay = c.days[0];
    if (firstDay < ws - c.usual_gap && we - ws >= c.usual_gap) {
      const inWindow = c.days.filter(d => d > ws && d <= we).length;
      const before = c.days.filter(d => d <= ws && d > ws - rules.seasonal_lookback).length;
      const after = c.days.filter(d => d > we && d <= we + rules.seasonal_lookback).length;
      if (inWindow === 0 && before > 0 && after > 0) {
        status = 'Seasonal';
        seasonal_note = `Also quiet from ${toIso(ws)} to ${toIso(we)} last year, then came back.`;
      }
    }
  }
  const dec = lastDecision[c.name];
  const snoozed = !!(dec && asOfDay - dec.day <= rules.snooze_days);
  const atRisk = (status === 'Slipping' || status === 'Gone Quiet') ? c.yearly_value : 0;
  const last3 = c.bills.slice(-3);
  const avgLast3 = last3.reduce((a, b) => a + b, 0) / (last3.length || 1);
  const basketChange = c.avg_bill ? Math.round((avgLast3 / c.avg_bill - 1) * 100) : 0;
  return {
    name: c.name, phone: c.phone, status, ratio: Math.round(ratio * 100) / 100,
    usual_gap: Math.round(c.usual_gap), days_silent: c.days_silent, last_order: c.last_order, first_order: c.first_order,
    visits: c.visits, avg_bill: c.avg_bill, yearly_value: c.yearly_value, at_risk: atRisk,
    basket_change_pct: basketChange, last_bills: c.bills.slice(-6), seasonal_note,
    decision: dec ? dec.decision : '', snoozed, last_items: c.last_items,
    months_as_customer: Math.max(1, Math.round((asOfDay - day(c.first_order)) / 30.4))
  };
});
out.sort((a, b) => (ORDER[a.status] - ORDER[b.status]) || (b.yearly_value - a.yearly_value));

const count = (s) => out.filter(c => c.status === s).length;
const actionable = out.filter(c => (c.status === 'Slipping' || c.status === 'Gone Quiet') && !c.snoozed)
  .sort((a, b) => b.yearly_value - a.yearly_value);
const top = actionable.slice(0, rules.ai_top).map((c, i) => ({ id: 'c' + (i + 1), ...c }));
const totals = {
  as_of: R.as_of, customers: out.length,
  healthy: count('Healthy'), watch: count('Watch'), slipping: count('Slipping'), gone_quiet: count('Gone Quiet'),
  seasonal: count('Seasonal'), too_new: count('Too New'),
  at_risk_total: out.reduce((a, c) => a + c.at_risk, 0),
  needs_action: actionable.length,
  call_today: actionable.slice(0, 3).map(c => c.name),
  seasonal_names: out.filter(c => c.status === 'Seasonal').map(c => c.name),
  snoozed: out.filter(c => c.snoozed && (c.status === 'Slipping' || c.status === 'Gone Quiet')).length
};

// a plain-words label of the pattern, so Agent 3 reasons from evidence, not a template
const patternOf = (c) => c.basket_change_pct <= -25 ? 'bills shrank over the last few orders before stopping'
  : c.days_silent > 120 ? 'went silent months ago with no shrinking first'
  : c.status === 'Gone Quiet' ? 'stopped suddenly after steady, full-size orders'
  : 'running late against their own usual rhythm';
const facts = top.map(c => ({
  id: c.id, customer: c.name, pattern: patternOf(c), long_standing: c.months_as_customer >= 12, status: c.status, usual_gap_days: c.usual_gap, days_silent: c.days_silent,
  last_order_date: c.last_order, orders_count: c.visits, avg_bill_rs: c.avg_bill, yearly_value_rs: c.yearly_value,
  last_bills_rs: c.last_bills, basket_change_pct: c.basket_change_pct, months_as_customer: c.months_as_customer
}));
const brief_facts = {
  'Business': rules.business_name, 'Regular customers judged': totals.customers,
  'Customers who broke their usual ordering pattern': totals.slipping + totals.gone_quiet,
  'Of those, slipping': totals.slipping, 'Of those, gone quiet': totals.gone_quiet,
  'A little late (watch list)': totals.watch, 'Seasonal, no action needed': totals.seasonal_names,
  'Rupees a year at risk': totals.at_risk_total, 'Call today': totals.call_today
};

return [{ json: { as_of: R.as_of, stats: R.stats, merges: R.merges, customers: out, top, totals,
  facts_text: JSON.stringify(facts, null, 1), brief_text: JSON.stringify(brief_facts, null, 1) } }];

// 16 Fact Guard
// Rejects any reason that contains a number the agent was never given and
// swaps in a plain reason built by code. Then prepares Agent 4's brief.
const J = $('14 Judge Status, Season And Money').first().json;
const S = $('07 Sample The Columns').first().json;
const parseAgent = (res) => {
  try {
    let t = res.candidates[0].content.parts.map(p => p.text || '').join('');
    t = t.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(t);
  } catch (e) { return {}; }
};
const got = {};
for (const r of (parseAgent($input.first().json).reasons || [])) if (r && r.id) got[r.id] = String(r.reason || '').trim();

const numbersIn = (s) => (String(s).replace(/(\d),(?=\d)/g, '$1').match(/\d+(\.\d+)?/g) || []).map(x => String(Number(x)));
const rejected = [];
const top = J.top.map(c => {
  const allowed = new Set(numbersIn(JSON.stringify(c)));
  let reason = got[c.id] || '';
  const bad = numbersIn(reason).filter(x => !allowed.has(x));
  if (!reason || bad.length || reason.length > 220 || /[–—]/.test(reason)) {
    if (reason) rejected.push({ id: c.id, reason, invented: bad });
    reason = c.basket_change_pct <= -25
      ? `Bill size fell ${Math.abs(c.basket_change_pct)}% across the last 3 orders before going quiet.`
      : `Usually orders every ${c.usual_gap} days and has now been silent for ${c.days_silent}.`;
  }
  return { ...c, reason };
});

const t = S.tone || {};
const r = S.rules;
const writer = top.map(c => ({ id: c.id, customer: c.customer || c.name, usual_gap_days: c.usual_gap, days_silent: c.days_silent, reason: c.reason }));
const tone_text = [
  'Business name: ' + (r.business_name || ''),
  'Owner name: ' + (t.owner_name || ''),
  'Greeting the owner uses: ' + (t.greeting || 'Namaste'),
  'Sign off: ' + (t.sign_off || ''),
  'Words and phrases the owner uses: ' + (t.words_to_use || ''),
  'Never use: ' + (t.words_to_avoid || ''),
  'Language: ' + (r.language || 'hinglish'),
  'Discounts allowed: ' + (String(r.allow_discount).toLowerCase() === 'yes' ? 'yes, at most a small one' : 'NO, never mention a discount, offer, cashback or free item')
].join('\n');

return [{ json: { top, rejected_reasons: rejected, writer_text: JSON.stringify(writer, null, 1), tone_text } }];

// 20 Package The Results
// Final code checks on every message and on the brief, then builds everything
// that leaves the desk: sheet rows, Telegram brief, customer cards, HTML email
// and the CSV attachment.
const S = $('07 Sample The Columns').first().json;
const C = $('09 Check And Clean').first().json;
const J = $('14 Judge Status, Season And Money').first().json;
const F = $('16 Fact Guard').first().json;
const rules = S.rules;
const tone = S.tone || {};
const parseAgent = (res) => {
  try {
    let t = res.candidates[0].content.parts.map(p => p.text || '').join('');
    t = t.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(t);
  } catch (e) { return {}; }
};
let drafts = {}, checked = {};
try { for (const m of (parseAgent($('17 Agent 4 · The Win-back Writer').first().json).messages || [])) drafts[m.id] = String(m.message || ''); } catch (e) {}
try { for (const m of (parseAgent($('18 Agent 5 · The Message Checker').first().json).checked || [])) checked[m.id] = m; } catch (e) {}
const briefAgent = parseAgent($input.first().json);

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rs = (n) => 'Rs ' + Math.round(Number(n) || 0).toLocaleString('en-IN');
const numbersIn = (s) => (String(s).replace(/(\d),(?=\d)/g, '$1').match(/\d+(\.\d+)?/g) || []).map(x => String(Number(x)));
const allowDiscount = String(rules.allow_discount).toLowerCase() === 'yes';
const hinglish = /hing|hindi/i.test(String(rules.language));

// ---------- messages ----------
const fallbackMsg = (c) => {
  const first = String(c.name).split(' ')[0];
  const g = tone.greeting || 'Namaste';
  const so = tone.sign_off ? ' ' + tone.sign_off : '';
  return hinglish
    ? `${g} ${first} ji, kaafi din se aapka order nahi aaya. Sab theek hai? Kuch bhi chahiye ho to bata dijiye, turant bhijwa denge.${so}`
    : `${g} ${first} ji, we have not had your usual order in a while. Hope all is well. If you need anything, just tell us and we will send it right away.${so}`;
};
const msgProblems = (m) => {
  const p = [];
  if (!m || m.length < 20) p.push('empty');
  if (m.length > 350) p.push('too long');
  if (/\d/.test(m)) p.push('contains a number');
  if (/[–—]/.test(m)) p.push('dash');
  if (/[\[\]{}]/.test(m)) p.push('placeholder');
  if (!allowDiscount && /discount|cashback|% ?off|\bfree\b|offer/i.test(m)) p.push('discount');
  if (/our system|tracking|our records|data shows|we noticed from|algorithm|\bAI\b/i.test(m)) p.push('sounds like surveillance');
  if (/you forgot|ignoring us|disappointed/i.test(m)) p.push('guilt trip');
  return p;
};
const top = F.top.map(c => {
  const ch = checked[c.id] || {};
  let msg = String(ch.message || drafts[c.id] || '').trim();
  let source = ch.message ? 'checked' : (drafts[c.id] ? 'draft' : 'none');
  const problems = msgProblems(msg);
  if (problems.length) { msg = fallbackMsg(c); source = 'code fallback (' + problems.join(', ') + ')'; }
  return { ...c, message: msg, message_source: source, checker_changes: Array.isArray(ch.changes) ? ch.changes : [] };
});
const byName = Object.fromEntries(top.map(c => [c.name, c]));

// ---------- brief ----------
const T = J.totals;
const allowedBrief = new Set(numbersIn(J.brief_text));
let lines = Array.isArray(briefAgent.lines) ? briefAgent.lines.map(String).filter(Boolean).slice(0, 6) : [];
const badBrief = lines.some(l => numbersIn(l).some(x => !allowedBrief.has(x)) || /[–—]/.test(l));
if (!lines.length || badBrief) {
  lines = [
    `${T.slipping + T.gone_quiet} regular customers have broken their usual ordering pattern.`,
    `${rs(T.at_risk_total)} a year of business is at risk.`,
    T.call_today.length ? `Call today: ${T.call_today.join(', ')}.` : 'Nobody needs a call today.',
    T.seasonal ? `${T.seasonal} marked seasonal, no action needed.` : 'No seasonal customers this week.',
    `${T.watch} more are a little late and on Watch.`
  ];
}
const st = J.stats;
const housekeeping = `Read ${Number(st.raw_rows).toLocaleString('en-IN')} rows: removed ${st.removed_returns} returns and ${st.removed_duplicates} duplicate bills, joined ${J.merges.length} name spellings, judged ${T.customers} customers as of ${J.as_of}.`;
const cardsN = Math.min(rules.cards, top.length);
const briefHtml = `<b>Monday brief · ${esc(rules.business_name)}</b>\n\n` + lines.map(esc).join('\n') +
  `\n\n<i>${esc(housekeeping)}</i>` + (cardsN ? `\n\nCards for the top ${cardsN} are below. Nothing is sent to any customer without your tap.` : '');

// ---------- sheet rows ----------
const WL_HEAD = ['customer', 'status', 'usual_gap_days', 'days_silent', 'last_order', 'orders', 'avg_bill_rs', 'yearly_value_rs', 'at_risk_rs', 'likely_reason', 'message', 'phone', 'decision', 'lateness_ratio', 'updated_on'];
const wl = J.customers.map(c => {
  const t = byName[c.name] || {};
  return [c.name, c.status, c.usual_gap, c.days_silent, c.last_order, c.visits, c.avg_bill, c.yearly_value, c.at_risk,
    t.reason || c.seasonal_note || '', t.message || '', c.phone ? "'" + c.phone : '', c.decision || '', c.ratio, J.as_of];
});
const pad = (rows, prevLen, width) => { const out = rows.slice(); while (out.length < prevLen) out.push(Array(width).fill('')); return out; };
const data = [{ range: 'Watchlist!A1', values: pad([WL_HEAD, ...wl], S.prev_watch_rows, WL_HEAD.length) }];

const RL_HEAD = ['run_date', 'healthy', 'watch', 'slipping', 'gone_quiet', 'seasonal', 'too_new', 'at_risk_rs', 'customers', 'needs_action'];
const runRow = [J.as_of, T.healthy, T.watch, T.slipping, T.gone_quiet, T.seasonal, T.too_new, T.at_risk_total, T.customers, T.needs_action];
const log = S.run_log || [];
const serial = Math.round(Date.parse(J.as_of + 'T00:00:00Z') / 86400000) + 25569;
let rowIdx = log.length ? log.length + 1 : 2;
for (let i = 1; i < log.length; i++) {
  const v = log[i][0];
  if (v === serial || String(v).slice(0, 10) === J.as_of) { rowIdx = i + 1; break; }
}
if (!log.length) data.push({ range: "'Run Log'!A1", values: [RL_HEAD] });
data.push({ range: `'Run Log'!A${rowIdx}`, values: [runRow] });

if (C.source === 'file') {
  const OH = ['customer', 'date', 'amount', 'invoice', 'phone', 'items'];
  const orows = C.orders.map(o => [o.customer, o.date, o.amount, o.invoice ? "'" + o.invoice : '', o.phone ? "'" + o.phone : '', o.items]);
  data.push({ range: 'Orders!A1', values: pad([OH, ...orows], S.prev_order_rows, OH.length) });
}
const chatIdx = (S.rules_keys || []).indexOf('owner_chat_id');
if (S.chat_id && chatIdx > 0 && String(S.rules.owner_chat_id || '') !== String(S.chat_id)) {
  data.push({ range: `Rules!B${chatIdx + 1}`, values: [["'" + S.chat_id]] });
}

// ---------- email ----------
const pill = (s) => {
  const m = { 'Slipping': ['#fdeee4', '#c2410c'], 'Gone Quiet': ['#fde8e8', '#b91c1c'] }[s] || ['#eef0f3', '#374151'];
  return `<span style="background:${m[0]};color:${m[1]};font-weight:bold;font-size:11px;padding:3px 7px;border-radius:999px;white-space:nowrap">${esc(s)}</span>`;
};
const tile = (n, label, bg, fg) => `<td width="25%" style="padding:4px"><div style="background:${bg};color:${fg};border-radius:8px;padding:10px;text-align:center;font-family:Arial,sans-serif"><div style="font-size:22px;font-weight:bold">${n}</div><div style="font-size:11px">${label}</div></div></td>`;
const topRows = top.slice(0, 8).map(c => `<tr><td style="padding:8px;border-bottom:1px solid #eef0f3">${esc(c.name)}<div style="color:#6b7280;font-size:11px;margin-top:2px">${esc(c.reason)}</div></td><td style="padding:8px;border-bottom:1px solid #eef0f3;white-space:nowrap">${c.usual_gap} days</td><td style="padding:8px;border-bottom:1px solid #eef0f3;white-space:nowrap">${c.days_silent} days</td><td style="padding:8px;border-bottom:1px solid #eef0f3;white-space:nowrap">${rs(c.yearly_value)}</td><td style="padding:8px;border-bottom:1px solid #eef0f3">${pill(c.status)}</td></tr>`).join('');
const dash = rules.dashboard_url ? `<a href="${esc(rules.dashboard_url)}" style="display:inline-block;background:#c2410c;color:#ffffff;text-decoration:none;padding:11px 18px;border-radius:8px;font-weight:bold;font-size:14px;font-family:Arial,sans-serif">Open the live dashboard</a>` : '';
const email_html = `<!doctype html><html><body style="margin:0;padding:0;background:#eef0f3">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef0f3;padding:20px 8px"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<tr><td style="background:#1b1a17;padding:22px 24px"><div style="color:#fdba74;font-size:11px;letter-spacing:2px;text-transform:uppercase">Quiet Churn Desk · Week of ${esc(J.as_of)}</div><div style="color:#ffffff;font-size:20px;font-weight:bold;margin-top:6px">${esc(rules.business_name)}, Monday report</div></td></tr>
<tr><td style="padding:22px 24px 6px"><div style="font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:1px">Yearly business at risk</div><div style="font-size:34px;font-weight:bold;color:#c2410c">${rs(T.at_risk_total)}</div><div style="font-size:13px;color:#4b5563">${T.slipping + T.gone_quiet} regular customers have broken their usual ordering pattern.</div></td></tr>
<tr><td style="padding:10px 20px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>${tile(T.healthy, 'Healthy', '#e7f5ec', '#15803d')}${tile(T.watch, 'Watch', '#fdf5dc', '#a16207')}${tile(T.slipping, 'Slipping', '#fdeee4', '#c2410c')}${tile(T.gone_quiet, 'Gone quiet', '#fde8e8', '#b91c1c')}</tr></table></td></tr>
<tr><td style="padding:6px 24px"><div style="font-size:14px;font-weight:bold;margin:8px 0">This week in five lines</div>${lines.map(l => `<div style="font-size:13px;color:#374151;margin:3px 0">${esc(l)}</div>`).join('')}</td></tr>
${top.length ? `<tr><td style="padding:10px 24px"><div style="font-size:14px;font-weight:bold;margin:8px 0">Call these first</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:12.5px;border-collapse:collapse"><tr style="background:#f3f4f6;color:#6b7280;font-size:10.5px;text-transform:uppercase"><td style="padding:8px">Customer</td><td style="padding:8px">Usual gap</td><td style="padding:8px">Silent</td><td style="padding:8px">Yearly value</td><td style="padding:8px">Status</td></tr>${topRows}</table></td></tr>` : ''}
${T.seasonal_names.length ? `<tr><td style="padding:6px 24px"><div style="background:#eff6ff;border-radius:8px;padding:10px 12px;font-size:12.5px;color:#1e3a8a"><b>Seasonal, no action needed:</b> ${esc(T.seasonal_names.join(', '))} were quiet in these same weeks last year too.</div></td></tr>` : ''}
<tr><td style="padding:16px 24px 22px">${dash}</td></tr>
<tr><td style="background:#f9fafb;color:#9ca3af;font-size:11px;padding:12px 24px">${esc(housekeeping)} Drafts are waiting for your approval on Telegram. Nothing is ever sent to a customer without your tap.</td></tr>
</table></td></tr></table></body></html>`;
const subject = `Monday report: ${rs(T.at_risk_total)} a year at risk from ${T.slipping + T.gone_quiet} customers`;

const csvCell = (v) => { const s = String(v === undefined || v === null ? '' : v).replace(/^'/, ''); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const csv = [WL_HEAD, ...wl].map(r => r.map(csvCell).join(',')).join('\n');

const shared = {
  chat_id: S.chat_id, brief_html: briefHtml, email_to: rules.email_to, email_subject: subject, email_html,
  sheet_body: { valueInputOption: 'USER_ENTERED', data }, totals: T, housekeeping
};

// ---------- cards ----------
const cards = top.slice(0, cardsN).map((c, i) => {
  const ph = /^[6-9]\d{9}$/.test(c.phone || '') ? c.phone : '';
  const text = `<b>${i + 1} of ${cardsN} · ${esc(c.name)} · ${esc(c.status.toUpperCase())}</b>\n` +
    `Usually orders every ${c.usual_gap} days. Last order ${c.days_silent} days ago.\n` +
    `Worth ${rs(c.yearly_value)} a year.\n` +
    `<i>Likely reason (a guess): ${esc(c.reason)}</i>\n` +
    (ph ? `Phone: ${ph}\n` : '') +
    `\nDraft:\n${esc(c.message)}`;
  const key = c.name.slice(0, 40);
  return { json: { is_card: true, chat_id: S.chat_id, card_text: text, cb_approve: 'a|' + key, cb_skip: 's|' + key, cb_seasonal: 'z|' + key } };
});
const items = cards.length ? cards : [{ json: { is_card: false, chat_id: S.chat_id } }];
items[0].json.shared = shared;
items[0].binary = { watchlist: { data: Buffer.from(csv, 'utf8').toString('base64'), mimeType: 'text/csv', fileName: `watchlist_${J.as_of}.csv`, fileExtension: 'csv' } };
return items;
